{"query": "
-- Index 1: Composite covering index on participants_events for participant_id + event_id
-- Eliminates seq scan in main GROUP BY and in SubPlan 3 (pe2 scan)
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_participants_events_participant_event
    ON participants_events (participant_id, event_id);
"}

{"query": "
-- Index 3: Index on events(id, start_date_time) — covering index for SubPlan 3 join + MAX()
-- Allows index-only scan when joining e.id = pe2.event_id and projecting start_date_time
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_events_id_start_datetime
    ON events (id, start_date_time);
"}
